queries.explanation:
PREFIX energia: <https://w3id.org/rastro/energia#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?concesion ?porcentaje ?produccion ?parte ?gas ?texto ?fuente ?empresa ?concesionIri ?participacion ?origen ?actividad ?regla WHERE {
  { SELECT ?c (SUM(?oil) AS ?prod) (SUM(?g) AS ?prodgas) WHERE {
      ?p a energia:WellProduction ; energia:inConcession ?c ; energia:oil ?oil ; energia:gas ?g .
      FILTER EXISTS { ?s0 a energia:Stake ; energia:inConcession ?c ; energia:partner/energia:name "CHEVRON" }
    } GROUP BY ?c }
  ?s a energia:Stake ; energia:inConcession ?c ; energia:partner ?empresa ; energia:percent ?porcentaje ;
     energia:sourceText ?texto ; energia:rule ?regla ; prov:wasDerivedFrom ?origen ; prov:wasGeneratedBy ?actividad .
  ?empresa energia:name "CHEVRON" .
  ?origen energia:name ?fuente .
  ?c energia:name ?concesion .
  BIND (?c AS ?concesionIri)
  BIND (?s AS ?participacion)
  BIND (?prod AS ?produccion)
  BIND (ROUND(?prod * ?porcentaje / 100) AS ?parte)
  BIND (ROUND(?prodgas * ?porcentaje / 100) AS ?gas)
} ORDER BY DESC(?parte)

queries.links:
PREFIX energia: <https://w3id.org/rastro/energia#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?nombre ?fuente ?regla ?evidencia ?empresa WHERE {
  ?empresa energia:name "CHEVRON" .
  ?enlace a energia:CompanyName ; energia:company ?empresa ; energia:nameInSource ?nombre ;
    energia:rule ?regla ; energia:sourceText ?evidencia ; prov:wasDerivedFrom/energia:name ?fuente .
} ORDER BY ?fuente ?nombre

queries.production_sample:
PREFIX energia: <https://w3id.org/rastro/energia#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?registro ?pozo ?mes ?petroleo ?fuente WHERE {
  ?concesion energia:name "LOMA CAMPANA" .
  ?registro a energia:WellProduction ; energia:inConcession ?concesion ;
    energia:well/energia:wellId ?pozo ; energia:oil ?petroleo ;
    energia:fromSource/energia:name ?fuente .
  BIND (STRAFTER(STR(?registro), "/production/") AS ?clave)
  BIND (STRBEFORE(STRAFTER(?clave, "/"), "/") AS ?mes)
} ORDER BY DESC(?petroleo) ?registro LIMIT 12
